create or replace package body margin_report as
  function margin_pct(p_sku in varchar2) return number is
    l_margin number;
  begin
    select margin_pct into l_margin from (
        select margin_pct from item_margins_v where sku = p_sku order by margin_pct desc
    ) where rownum = 1;
    return l_margin;
  end margin_pct;
end margin_report;
